#[path="/workspace/codecortex/crates/cc-search/src/dsl.rs"] mod dsl;
#[path="/workspace/codecortex/crates/cc-search/src/query_target.rs"] mod query_target;
fn main(){let rows:serde_json::Value=serde_json::from_str(include_str!("/workspace/query-owner-v3-direct/probes.json")).unwrap();let mut out=Vec::new();for row in rows.as_array().unwrap(){let q=row["query"].as_str().unwrap();let parsed=dsl::parse_search_dsl(q);let target=query_target::QueryTarget::parse(&parsed);let ctx=query_target::NameBonusContext::parse(&parsed,&target);let tokens=cc_db::fts::tokenize_codeish(&parsed.text);let kinds=["class","interface","type_alias","enum","module","namespace","method","function","unknown"];let flags:Vec<_>=kinds.iter().map(|k|serde_json::json!({"kind":k,"owner":ctx.permits("Beacon",Some(k)),"other":ctx.permits("Sink",Some(k)),"target_owner":target.permits("Beacon",Some(k),&tokens),"target_member":target.permits("Commit",Some(k),&tokens)})).collect();out.push(serde_json::json!({"query":q,"target":format!("{:?}",target),"context":format!("{:?}",ctx),"flags":flags,"comparative":row["comparative"],"family":row["family"],"explicit_bypass":row["explicit_bypass"]}));}println!("{}",serde_json::to_string_pretty(&out).unwrap());}
